const router = Router();

/* ====================================================================== */
/*  IN-MEMORY CACHE (60s TTL)                                              */
/* ====================================================================== */

interface CacheEntry<T> {
  data: T;
  generatedAt: number;
}

const ENHANCED_CACHE_TTL_MS = 60 * 1000; // 60 seconds
const dealCache = new Map<number, CacheEntry<any>>();
const forecastCache = new Map<number, CacheEntry<any>>();

function getCached<T>(cache: Map<number, CacheEntry<T>>, key: number): T | null {
  const entry = cache.get(key);
  if (entry && (Date.now() - entry.generatedAt) < ENHANCED_CACHE_TTL_MS) {
    return entry.data;
  }
  return null;
}

function setCached<T>(cache: Map<number, CacheEntry<T>>, key: number, data: T) {
  cache.set(key, { data, generatedAt: Date.now() });
}

/* ====================================================================== */
/*  HELPERS                                                                */
/* ====================================================================== */

async function buildSailingContext(sailingId: number, preferences?: { tripType?: string; cabinPriorities?: string[] }): Promise<SailingContext | null> {
  const pool = getPool();
  console.log('[BUILD_CONTEXT] Starting for sailing', sailingId);

  // Fetch sailing data
  const sailingResult = await pool.query(
    `SELECT id, cruise_line, ship_name, duration_days, departure_port,
            destination_region, departure_date, itinerary, cabin_categories, booking_url
     FROM sailings WHERE id = $1`,
    [sailingId]
  );

  if (sailingResult.rows.length === 0) return null;
  const s = sailingResult.rows[0];
  console.log('[BUILD_CONTEXT] Sailing fetched:', s.cruise_line, s.ship_name);

  // Fetch current pricing (latest snapshot per cabin)
  const pricingResult = await pool.query(
    `SELECT cabin_type, total_out_the_door_usd
     FROM pricing_snapshots
     WHERE sailing_id = $1
     ORDER BY captured_at DESC`,
    [sailingId]
  );

  const currentPricing: Record<string, number> = {};
  for (const p of pricingResult.rows) {
    if (!(p.cabin_type in currentPricing)) {
      currentPricing[p.cabin_type] = parseFloat(p.total_out_the_door_usd);
    }
  }

  // Fetch pricing history (last 20 snapshots for Inside cabin)
  const historyResult = await pool.query(
    `SELECT cabin_type, total_out_the_door_usd, captured_at
     FROM pricing_snapshots
     WHERE sailing_id = $1 AND cabin_type = 'Inside'
     ORDER BY captured_at ASC
     LIMIT 20`,
    [sailingId]
  );

  const priceHistory = historyResult.rows.map((r: any) => ({
    cabinType: r.cabin_type,
    price: parseFloat(r.total_out_the_door_usd),
    date: r.captured_at,
  })) || [];

  // Fetch ship details (if available)
  let shipDetails: SailingContext['shipDetails'] = undefined;
  try {
    const shipResult = await pool.query(
      `SELECT year_built, passenger_capacity, tonnage
       FROM ship_details WHERE ship_name = $1 LIMIT 1`,
      [s.ship_name]
    );
    console.log('[BUILD_CONTEXT] Ship query done');
    if (shipResult.rows.length > 0) {
      const sd = shipResult.rows[0];
      shipDetails = {
        yearBuilt: sd.year_built,
        passengerCapacity: sd.passenger_capacity,
        tonnage: sd.tonnage,
      };
    }
  } catch { /* ship_details may not exist yet */ }

  // Fetch destination insight (if available)
  let destinationInsight: SailingContext['destinationInsight'] = undefined;
  try {
    const destResult = await pool.query(
      `SELECT avg_price_ppd, best_value_months, peak_season_months, price_trend
       FROM destination_insights WHERE destination_region = $1 LIMIT 1`,
      [s.destination_region]
    );
    console.log('[BUILD_CONTEXT] Destination query done');
    if (destResult.rows.length > 0) {
      const di = destResult.rows[0];
      destinationInsight = {
        avgPricePpd: di.avg_price_ppd,
        bestValueMonths: typeof di.best_value_months === 'string' ? JSON.parse(di.best_value_months) : di.best_value_months,
        peakSeasonMonths: typeof di.peak_season_months === 'string' ? JSON.parse(di.peak_season_months) : di.peak_season_months,
        priceTrend: di.price_trend,
      };
    }
  } catch { /* destination_insights may not exist yet */ }

  // Fetch market comparison (if available)
  let marketComparison: SailingContext['marketComparison'] = undefined;
  try {
    const mktResult = await pool.query(
      `SELECT avg_price_ppd, overall_rating, best_value_rating
       FROM market_comparisons WHERE cruise_line = $1 LIMIT 1`,
      [s.cruise_line]
    );
    console.log('[BUILD_CONTEXT] Market query done');
    if (mktResult.rows.length > 0) {
      const mc = mktResult.rows[0];
      marketComparison = {
        avgPricePpd: mc.avg_price_ppd,
        overallRating: mc.overall_rating,
        bestValueRating: mc.best_value_rating,
      };
    }
  } catch { /* market_comparisons may not exist yet */ }

  return {
    sailingId: s.id,
    cruiseLine: s.cruise_line,
    shipName: s.ship_name,
    durationDays: s.duration_days,
    departurePort: s.departure_port,
    destinationRegion: s.destination_region,
    departureDate: s.departure_date,
    itinerary: s.itinerary,
    cabinCategories: s.cabin_categories,
    bookingUrl: s.booking_url,
    currentPricing,
    priceHistory,
    shipDetails,
    destinationInsight,
    marketComparison,
    tripType: preferences?.tripType,
    cabinPriorities: preferences?.cabinPriorities,
  };
}


  async function findCompetingSailings(sailingId: number): Promise<CompetingSailingData[]> {
  const pool = getPool();
  console.log('[FIND_COMP] Starting for sailing', sailingId);
  
  // Get current sailing's route and date
  const currentResult = await pool.query(
    `SELECT destination_region, departure_date, duration_days, cruise_line, ship_name
     FROM sailings WHERE id = $1`,
    [sailingId]
  );
  console.log('[FIND_COMP] Current sailing fetched');
  if (currentResult.rows.length === 0) return [];

  const current = currentResult.rows[0];

  // Find other sailings on same route, similar dates (±14 days), different ship
  const compDate = new Date(current.departure_date).toISOString().split('T')[0];
  const compResult = await pool.query(
    `SELECT s.id AS sailing_id, s.cruise_line, s.ship_name, s.departure_date,
            MIN(ps.total_out_the_door_usd) AS balcony_price
     FROM sailings s
     INNER JOIN pricing_snapshots ps ON ps.sailing_id = s.id AND ps.cabin_type = 'Balcony'
     WHERE s.destination_region = $1
       AND s.id != $2
       AND s.sync_status = 'active'
       AND (s.departure_date::date - $3::date) BETWEEN -14 AND 14
     GROUP BY s.id, s.cruise_line, s.ship_name, s.departure_date
     ORDER BY ABS(s.departure_date::date - $3::date) ASC
     LIMIT 5`,
    [current.destination_region, sailingId, compDate]
  );

  console.log('[FIND_COMP] Competitors found:', compResult.rows.length);
  // Fetch current sailing's balcony price for delta calculation
  const currentBalconyResult = await pool.query(
    `SELECT MIN(ps.total_out_the_door_usd) AS balcony_price
     FROM pricing_snapshots ps
     WHERE ps.sailing_id = $1 AND ps.cabin_type = 'Balcony'`,
    [sailingId]
  );
  const currentBalconyPrice = currentBalconyResult.rows.length > 0
    ? parseFloat(currentBalconyResult.rows[0].balcony_price) : null;

  return compResult.rows.map((r: any) => ({
    sailingId: r.sailing_id,
    cruiseLine: r.cruise_line,
    shipName: r.ship_name,
    departureDate: r.departure_date,
    balconyPrice: parseFloat(r.balcony_price),
    priceDifference: currentBalconyPrice ? Math.round(parseFloat(r.balcony_price) - currentBalconyPrice) : 0,
  }));
}

/* ====================================================================== */
