/**
 * GET /api/enhanced/deal-analysis/:sailingId
 * Returns the enhanced deal analysis for a specific sailing.
 * Uses cached data if available, otherwise generates on-demand.
 */
router.get('/deal-analysis/:sailingId', async (req: Request, res: Response) => {
  try {
    const sailingId = parseInt(req.params.sailingId, 10);
    if (isNaN(sailingId)) {
      return res.status(400).json({ success: false, error: 'Invalid sailing ID' });
    }

    // Check in-memory cache
    if (req.query.forceRefresh !== 'true') {
      const cached = getCached(dealCache, sailingId);
      if (cached) {
        return res.json({
          success: true,
          data: cached,
          generatedAt: new Date().toISOString(),
          cached: true,
        });
      }
    }

    const context = await buildSailingContext(sailingId);
    if (!context) {
      return res.status(404).json({ success: false, error: 'Sailing not found' });
    }

    const forceRefresh = req.query.forceRefresh === 'true';
    const result = await generateEnhancedDealAnalysis(context, forceRefresh);
    const sanitized = sanitizeDealAnalysisObject(result as unknown as Record<string, unknown>) as unknown as typeof result;
    
    // Store in cache
    if (req.query.forceRefresh !== 'true') {
      setCached(dealCache, sailingId, sanitized);
    }
    
    return res.json({
      success: true,
      data: sanitized,
      generatedAt: new Date().toISOString(),
      cached: false,
    });
  } catch (err: any) {
    console.error('[ENHANCED] Deal analysis route error:', err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

