/**
 * GET /api/enhanced/stats
 * Returns statistics about enhanced analytics coverage.
 */
router.get('/stats', async (_req: Request, res: Response) => {
  try {
    const pool = getPool();

    const dealResult = await pool.query(
      `SELECT COUNT(*) AS count FROM sailings WHERE deal_analysis IS NOT NULL`
    );
    const forecastResult = await pool.query(
      `SELECT COUNT(*) AS count FROM sailings WHERE price_forecast IS NOT NULL`
    );
    const totalResult = await pool.query(
      `SELECT COUNT(*) AS count FROM sailings WHERE sync_status = 'active'`
    );

    return res.json({
      success: true,
      data: {
        enhancedDealAnalyses: parseInt(dealResult.rows[0].count, 10),
        enhancedPriceForecasts: parseInt(forecastResult.rows[0].count, 10),
        totalActiveSailings: parseInt(totalResult.rows[0].count, 10),
      },
    });
  } catch (err: any) {
    console.error('[ENHANCED] Stats error:', err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

/**
 * POST /api/enhanced/batch-analyze
 * Batch-regenerate enhanced deal analyses (admin).
 * Query params: cruiseLine (optional), limit (default 10)
 */
router.post('/batch-analyze', async (req: Request, res: Response) => {
  try {
    const { cruiseLine, limit = 10 } = req.body;
    const parsedLimit = Math.min(50, Math.max(1, parseInt(limit as string, 10) || 10));

    const pool = getPool();
    let query = `SELECT id, cruise_line, ship_name, duration_days, departure_port,
                        destination_region, departure_date, itinerary, cabin_categories, booking_url
                 FROM sailings WHERE sync_status = 'active'`;
    const params: any[] = [];
    let paramIndex = 1;

    if (cruiseLine) {
      query += ` AND cruise_line = $${paramIndex}`;
      params.push(cruiseLine);
      paramIndex++;
    }

    query += ` ORDER BY id LIMIT $${paramIndex}`;
    params.push(parsedLimit);

    const result = await pool.query(query, params);

    // Build contexts and process
    const contexts: SailingContext[] = [];
    for (const s of result.rows) {
      const pricingSnap = await pool.query(
        `SELECT cabin_type, total_out_the_door_usd FROM pricing_snapshots WHERE sailing_id = $1 ORDER BY captured_at DESC`,
        [s.id]
      );
      const currentPricing: Record<string, number> = {};
      for (const p of pricingSnap.rows) {
        if (!(p.cabin_type in currentPricing)) {
          currentPricing[p.cabin_type] = parseFloat(p.total_out_the_door_usd);
        }
      }

      contexts.push({
        sailingId: s.id,
        cruiseLine: s.cruise_line,
        shipName: s.ship_name,
        durationDays: s.duration_days,
        departurePort: s.departure_port,
        destinationRegion: s.destination_region,
        departureDate: s.departure_date,
        itinerary: s.itinerary,
        cabinCategories: s.cabin_categories,
        bookingUrl: s.booking_url,
        currentPricing,
        priceHistory: [],
      });
    }

    const msg = await batchGenerateEnhancedDealAnalyses(contexts, true);
    return res.json({ success: true, data: msg });
  } catch (err: any) {
    console.error('[ENHANCED] Batch analyze error:', err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});


/**
 * POST /api/enhanced/regenerate-all
 * Scans all active sailings for stale/degraded deal analysis and regenerates them.
 * Body: { limit: number } default 20, max 50
 * Returns: count of fixed entries and list of IDs that were regenerated.
 */
router.post('/regenerate-all', async (req: Request, res: Response) => {
  try {
    const limit = Math.min(50, Math.max(1, parseInt(req.body.limit as string, 10) || 20));
    const pool = getPool();

    // Find sailings with deal_analysis that contain placeholder patterns
    const placeholderPatterns = [
      'analysis parsing failed',
      'data unavailable',
      'contact agent for details',
      'manual review recommended',
    ];

    // Build ILIKE conditions for each pattern
    const conditions = placeholderPatterns.map((p, i) =>
      `(deal_analysis::text ILIKE '%${p}%' OR (deal_analysis::json->>'pricingDeepDive')::text LIKE '%${p}%')`
    );
    conditions.push(`LENGTH(deal_analysis::json->>'pricingDeepDive'::text) < 30`);

    const whereClause = conditions.join(' OR ');
    const query = `SELECT id, cruise_line, ship_name FROM sailings WHERE deal_analysis IS NOT NULL AND (${whereClause}) ORDER BY id LIMIT $1`;

    const result = await pool.query(query, [limit]);

    let fixedCount = 0;
    const fixedIds: number[] = [];

    for (const row of result.rows) {
      try {
        const sailingId = row.id;
        const context = await buildSailingContext(sailingId);
        if (!context) {
          console.log(`[REGENERATE] Skipping ${sailingId}: context build failed`);
          continue;
        }
        await generateEnhancedDealAnalysis(context, true);
        fixedIds.push(sailingId);
        fixedCount++;
        console.log(`[REGENERATE] Fixed sailing ${sailingId} (${row.cruise_line} - ${row.ship_name})`);
      } catch (err: any) {
        console.error(`[REGENERATE] Failed to fix sailing ${row.id}: ${err.message}`);
      }
    }

    return res.json({
      success: true,
      data: {
        fixed: fixedCount,
        totalFound: result.rows.length,
        sailingIds: fixedIds,
      },
    });
  } catch (err: any) {
    console.error('[REGENERATE] Error:', err.message);
    res.status(500).json({ success: false, error: err.message });
  }
});

export default router;
